-- CirrusAtlantic: the one Company Code has one default operational owner.
DO $cirrus_operating_organizations$
DECLARE v_tenant_id uuid; v_actor uuid; v_org uuid; v_company uuid; v_meta constant jsonb:='{"_seed":{"pack":"cirrusatlantic.operating-organizations","version":"2.0.0"},"context":{"is_company_default":true}}'::jsonb;
BEGIN
 SELECT id INTO v_tenant_id FROM master.tenant WHERE realm_key='athyper' AND code='cirrusatlantic'; IF v_tenant_id IS NULL THEN RAISE EXCEPTION '[202_operating_organizations] CirrusAtlantic tenant not found'; END IF;
 SELECT id INTO v_actor FROM master.principal WHERE tenant_id=v_tenant_id AND code='seed.three-plane-provisioner' AND status='active'; IF v_actor IS NULL THEN RAISE EXCEPTION '[202_operating_organizations] CirrusAtlantic seed principal not found'; END IF;
 PERFORM set_config('app.current_principal_id',v_actor::text,true);
 SELECT id INTO v_company FROM master.company_code WHERE tenant_id=v_tenant_id AND code='catl'; IF v_company IS NULL THEN RAISE EXCEPTION '[202_operating_organizations] CATL company code not found'; END IF;
INSERT INTO master.operating_organization (tenant_id,code,name,description,organization_kind,effective_from,metadata,status,created_by) VALUES (v_tenant_id,'catl-company-operations','CirrusAtlantic Company Operations','Default owner for all CirrusAtlantic transactions.','company_operations',current_date,v_meta,'active',v_actor) ON CONFLICT (tenant_id,code) DO UPDATE SET name=EXCLUDED.name,description=EXCLUDED.description,organization_kind=EXCLUDED.organization_kind,metadata=master.operating_organization.metadata||EXCLUDED.metadata,status='active',updated_at=now(),updated_by=v_actor;
 SELECT id INTO v_org FROM master.operating_organization WHERE tenant_id=v_tenant_id AND code='catl-company-operations';
 INSERT INTO master.operating_organization_company_assignment (tenant_id,operating_organization_id,company_code_id,participation_role,effective_from,metadata,status,created_by) VALUES (v_tenant_id,v_org,v_company,'lead',current_date,v_meta,'active',v_actor) ON CONFLICT (tenant_id,operating_organization_id,company_code_id,effective_from) DO UPDATE SET participation_role='lead',metadata=EXCLUDED.metadata,status='active',effective_until=NULL,updated_at=now(),updated_by=v_actor;
 INSERT INTO master.operating_organization_capability(tenant_id,operating_organization_id,capability_code,effective_from,metadata,status,created_by) SELECT v_tenant_id,v_org,capability.code,current_date,v_meta,'active',v_actor FROM unnest(ARRAY['finance','procurement','people','sales','operations','warehouse','projects']) capability(code) ON CONFLICT(tenant_id,operating_organization_id,capability_code,effective_from) DO UPDATE SET status='active',metadata=EXCLUDED.metadata,updated_at=now(),updated_by=v_actor;
INSERT INTO master.procurement_organization_profile (tenant_id,operating_organization_id,buying_model,default_currency,lead_company_code_id,metadata,created_by) SELECT v_tenant_id,v_org,'federated',functional_currency,id,v_meta,v_actor FROM master.company_code WHERE tenant_id=v_tenant_id AND id=v_company ON CONFLICT (tenant_id,operating_organization_id) DO UPDATE SET buying_model=EXCLUDED.buying_model,default_currency=EXCLUDED.default_currency,lead_company_code_id=EXCLUDED.lead_company_code_id,metadata=EXCLUDED.metadata,updated_at=now(),updated_by=v_actor;
INSERT INTO master.sales_organization_profile (tenant_id,operating_organization_id,selling_model,default_currency,booking_company_code_id,invoicing_company_code_id,metadata,created_by) SELECT v_tenant_id,v_org,'federated',functional_currency,id,id,v_meta,v_actor FROM master.company_code WHERE tenant_id=v_tenant_id AND id=v_company ON CONFLICT (tenant_id,operating_organization_id) DO UPDATE SET selling_model=EXCLUDED.selling_model,default_currency=EXCLUDED.default_currency,booking_company_code_id=EXCLUDED.booking_company_code_id,invoicing_company_code_id=EXCLUDED.invoicing_company_code_id,metadata=EXCLUDED.metadata,updated_at=now(),updated_by=v_actor;
END;
$cirrus_operating_organizations$;
